export type Errors = { name?: string; email?: string; message?: string };

export function validate(v: { name: string; email: string; message: string }): Errors {
  const errors: Errors = {};
  const name = v.name.trim();
  const email = v.email.trim();
  const message = v.message.trim();
  if (!name) errors.name = 'Name is required.';
  if (!email) errors.email = 'Email is required.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.email = 'Enter a valid email address.';
  if (message.length < 20) errors.message = 'Message must be at least 20 characters.';
  return errors;
}
