---
import Layout from '../../layouts/Layout.astro';
import NotFound from '../../components/NotFound.astro';
import { getEntry, render } from 'astro:content';
const entry = await getEntry('books', Astro.params.slug ?? '');
if (!entry) Astro.response.status = 404;
const Content = entry ? (await render(entry)).Content : null;
---
{entry ? (
  <Layout title={`${entry.data.title} | Bookshelf`}>
    <h1>{entry.data.title}</h1>
    <p>by {entry.data.author}</p>
    <p>Published in {entry.data.year}</p>
    <p>Rating: {entry.data.rating}/5</p>
    <ul>
      {entry.data.tags.map((t) => <li><a href="/books">{t}</a></li>)}
    </ul>
    <div>{Content && <Content />}</div>
    <button type="button" id="fav" data-slug={entry.id}>Add to favorites</button>
    <script>
      import { getFavorites, setFavorites } from '../../lib/favorites';
      const btn = document.getElementById('fav') as HTMLButtonElement;
      const slug = btn.dataset.slug!;
      const paint = () => {
        btn.textContent = getFavorites().includes(slug) ? 'Remove from favorites' : 'Add to favorites';
      };
      paint();
      btn.addEventListener('click', () => {
        const l = getFavorites();
        setFavorites(l.includes(slug) ? l.filter((s) => s !== slug) : [...l, slug]);
        paint();
      });
    </script>
  </Layout>
) : (
  <Layout title="Not found | Bookshelf"><NotFound /></Layout>
)}
