---
import Layout from '../layouts/Layout.astro';
import { validate, type Errors } from '../lib/validate';
let values = { name: '', email: '', message: '' };
let errors: Errors = {};
let success = '';
if (Astro.request.method === 'POST') {
  const data = await Astro.request.formData();
  const get = (k: string) => String(data.get(k) ?? '');
  values = { name: get('name'), email: get('email'), message: get('message') };
  errors = validate(values);
  if (Object.keys(errors).length === 0) success = `Thanks, ${values.name.trim()}! Your message has been sent.`;
}
---
<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <div id="contact-region">
    {success ? (
      <p id="success">{success}</p>
    ) : (
      <form method="POST" action="/contact" novalidate id="contact-form">
        <div>
          <label for="name">Name</label>
          <input type="text" id="name" name="name" value={values.name} />
          <p class="error" data-for="name">{errors.name}</p>
        </div>
        <div>
          <label for="email">Email</label>
          <input type="email" id="email" name="email" value={values.email} />
          <p class="error" data-for="email">{errors.email}</p>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message">{values.message}</textarea>
          <p class="error" data-for="message">{errors.message}</p>
        </div>
        <button type="submit">Send</button>
      </form>
    )}
  </div>
  <script>
    import { validate } from '../lib/validate';
    const form = document.getElementById('contact-form') as HTMLFormElement | null;
    form?.addEventListener('submit', async (e) => {
      e.preventDefault();
      const f = form.elements as unknown as Record<string, HTMLInputElement>;
      const errors = validate({ name: f.name.value, email: f.email.value, message: f.message.value });
      form.querySelectorAll<HTMLElement>('.error').forEach((p) => {
        p.textContent = errors[p.dataset.for as keyof typeof errors] ?? '';
      });
      if (Object.keys(errors).length) return;
      const res = await fetch('/contact', { method: 'POST', body: new URLSearchParams(new FormData(form) as any) });
      const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
      const region = doc.getElementById('contact-region');
      if (region) document.getElementById('contact-region')!.innerHTML = region.innerHTML;
    });
  </script>
</Layout>
